/* Обществознание: прототипы к №9–16 */
(function () {
const S = window.SUBJECTS.find(s => s.id === 'social');
const SEL = '\n\nВыберите выводы, которые можно сделать на основе данных таблицы, и запишите цифры, под которыми они указаны.\n';
const ADD = {
  9: [
    { q: 'В ходе социологического опроса граждан страны Z задавали вопрос: «Какой источник информации о событиях в стране вы считаете для себя основным?» Результаты опроса (в % от числа опрошенных в каждой группе) представлены в таблице.\nИсточник — 18–30 лет — 31–50 лет — Старше 50 лет\nТелевидение — 12 — 35 — 64\nИнтернет-издания и соцсети — 70 — 45 — 14\nПечатная пресса — 3 — 8 — 15\nРадио — 5 — 7 — 4\nЗатрудняюсь ответить — 10 — 5 — 3' + SEL +
      '1) Большинство молодых людей 18–30 лет основным источником информации считают интернет-издания и социальные сети.\n2) Доля считающих основным источником телевидение растёт с возрастом опрошенных.\n3) Граждане старше 50 лет называли печатную прессу чаще, чем радио и интернет-издания вместе взятые.\n4) Радио — наименее популярный источник информации во всех возрастных группах.\n5) Доля затруднившихся с ответом среди молодёжи 18–30 лет вдвое больше, чем среди граждан 31–50 лет.',
      a: '125', s: ['1) 70% — больше половины: верно.', '2) 12 → 35 → 64: верно.', '3) 15 < 4 + 14 = 18: неверно.', '4) В группе 18–30 лет пресса (3) популярна меньше, чем радио (5): неверно.', '5) 10 и 5 — вдвое: верно.'] },
    { q: 'Социологическая служба страны Z в 2015 и 2025 гг. спрашивала совершеннолетних граждан: «Как вы относитесь к дистанционному обучению в вузах?» Результаты опроса (в % от числа опрошенных) представлены в таблице.\nВариант ответа — 2015 г. — 2025 г.\nПоложительно — 18 — 41\nСкорее положительно — 22 — 25\nСкорее отрицательно — 30 — 17\nОтрицательно — 20 — 9\nЗатрудняюсь ответить — 10 — 8' + SEL +
      '1) Доля затруднившихся с ответом за десять лет выросла.\n2) В 2025 г. большинство опрошенных относились к дистанционному обучению положительно или скорее положительно.\n3) В 2025 г. ответ «скорее отрицательно» выбрали вдвое больше опрошенных, чем в 2015 г.\n4) В 2015 г. ровно половина опрошенных относилась к дистанционному обучению отрицательно или скорее отрицательно.\n5) За десять лет доля относящихся к дистанционному обучению отрицательно сократилась более чем вдвое.',
      a: '245', s: ['1) 10 → 8 — снизилась: неверно.', '2) 41 + 25 = 66% > 50%: верно.', '3) 30 → 17 — снизилась: неверно.', '4) 30 + 20 = 50%: верно.', '5) 20 → 9, а 9 < 20 : 2 = 10: верно.'] },
    { q: 'Работающих мужчин и женщин страны Z спросили: «Что для вас самое важное при выборе места работы?» (можно было выбрать один вариант). Результаты опроса (в % от числа опрошенных в каждой группе) представлены в таблице.\nКритерий — Мужчины — Женщины\nВысокая зарплата — 48 — 36\nУдобный график — 10 — 24\nИнтересная работа — 20 — 18\nКарьерный рост — 15 — 8\nХороший коллектив — 7 — 14' + SEL +
      '1) Высокую зарплату чаще называли мужчины, чем женщины.\n2) Большинство мужчин главным критерием выбора работы считают высокую зарплату.\n3) Доля женщин, назвавших удобный график, более чем вдвое превышает долю мужчин, выбравших этот вариант.\n4) Для женщин хороший коллектив важнее, чем карьерный рост.\n5) Интересную работу мужчины и женщины назвали в равных долях.',
      a: '134', s: ['1) 48 > 36: верно.', '2) 48% — меньше половины: неверно.', '3) 24 > 2 · 10 = 20: верно.', '4) 14 > 8: верно.', '5) 20 ≠ 18: неверно.'] },
    { q: 'В 2020 и 2025 гг. граждан страны Z спрашивали: «Каким из перечисленных институтов вы доверяете?» (можно было выбрать несколько вариантов). Результаты опроса (в % от числа опрошенных) представлены в таблице.\nИнститут — 2020 г. — 2025 г.\nАрмия — 62 — 70\nЦерковь — 45 — 43\nПолиция — 30 — 38\nСуды — 22 — 27\nПолитические партии — 15 — 12' + SEL +
      '1) Доверие ко всем перечисленным институтам за пять лет выросло.\n2) Доля доверяющих полиции и судам за пять лет увеличилась.\n3) В 2025 г. политическим партиям доверяла меньшая доля граждан, чем в 2020 г.\n4) В 2020 г. большинство опрошенных доверяли церкви.\n5) В 2025 г. доля доверяющих судам более чем вдвое превышала долю доверяющих политическим партиям.',
      a: '235', s: ['1) Доверие к церкви (45 → 43) и партиям (15 → 12) снизилось: неверно.', '2) Полиция 30 → 38, суды 22 → 27: верно.', '3) 15 → 12: верно.', '4) 45% — не большинство: неверно.', '5) 27 > 2 · 12 = 24: верно.'] },
    { q: 'Граждан страны Z с высшим и средним образованием спросили: «Сколько книг вы прочитали за последний год?» Результаты опроса (в % от числа опрошенных в каждой группе) представлены в таблице.\nОтвет — Высшее образование — Среднее образование\nНи одной — 15 — 38\n1–3 книги — 30 — 34\n4–10 книг — 35 — 20\nБолее 10 книг — 20 — 8' + SEL +
      '1) Доля не прочитавших за год ни одной книги среди людей с высшим образованием выше, чем среди людей со средним образованием.\n2) Большинство людей с высшим образованием прочитали за год более трёх книг.\n3) Среди людей со средним образованием наиболее многочисленна группа не прочитавших ни одной книги.\n4) Большинство людей со средним образованием прочитали за год не менее четырёх книг.\n5) Доля прочитавших более 10 книг среди людей с высшим образованием в 2,5 раза больше, чем среди людей со средним образованием.',
      a: '235', s: ['1) 15 < 38: неверно.', '2) 35 + 20 = 55% > 50%: верно.', '3) 38 — наибольшее значение в столбце: верно.', '4) 20 + 8 = 28%: неверно.', '5) 20 : 8 = 2,5: верно.'] },
    { q: 'Накануне выборов жителей городов и сёл страны Z спросили: «Примете ли вы участие в предстоящих выборах?» Результаты опроса (в % от числа опрошенных в каждой группе) представлены в таблице.\nОтвет — Жители городов — Жители сёл\nОбязательно приму — 42 — 55\nСкорее приму — 18 — 20\nСкорее не приму — 15 — 10\nТочно не приму — 17 — 7\nЕщё не решил — 8 — 8' + SEL +
      '1) Горожане чаще сельских жителей выбирали ответ «скорее приму».\n2) Большинство сельских жителей твёрдо намерены принять участие в выборах.\n3) Более трети горожан не собираются (точно или скорее) участвовать в выборах.\n4) Доля горожан, точно не собирающихся голосовать, более чем вдвое выше доли таких сельских жителей.\n5) Доля не определившихся с решением одинакова среди жителей городов и сёл.',
      a: '245', s: ['1) 18 < 20: неверно.', '2) «Обязательно приму» — 55% > 50%: верно.', '3) 15 + 17 = 32% — меньше трети: неверно.', '4) 17 > 2 · 7 = 14: верно.', '5) 8 и 8: верно.'] },
    { q: 'В 2005, 2015 и 2025 гг. совершеннолетних граждан страны Z спрашивали: «Какое количество детей вы считаете идеальным для семьи?» Результаты опроса (в % от числа опрошенных) представлены в таблице.\nОтвет — 2005 г. — 2015 г. — 2025 г.\nНи одного — 4 — 6 — 9\nОдин — 22 — 18 — 20\nДва — 51 — 46 — 40\nТри и более — 15 — 24 — 25\nЗатрудняюсь ответить — 8 — 6 — 6' + SEL +
      '1) Доля считающих идеальной семью без детей от опроса к опросу росла.\n2) Во все годы большинство опрошенных считали идеальной семью с двумя детьми.\n3) За двадцать лет доля сторонников семьи с тремя и более детьми выросла.\n4) Доля считающих идеальным одного ребёнка от опроса к опросу снижалась.\n5) В 2025 г. семью с двумя детьми идеальной считали вдвое больше опрошенных, чем семью с одним ребёнком.',
      a: '135', s: ['1) 4 → 6 → 9: верно.', '2) В 2015 г. — 46%, в 2025 г. — 40%, это не большинство: неверно.', '3) 15 → 25: верно.', '4) 22 → 18 → 20 — в 2025 г. выросла: неверно.', '5) 40 и 20: верно.'] },
    { q: 'Граждан страны Z разного возраста спросили: «Как часто вы занимаетесь физкультурой или спортом?» Результаты опроса (в % от числа опрошенных в каждой группе) представлены в таблице.\nОтвет — 18–24 года — 25–44 года — 45 лет и старше\nЕжедневно — 20 — 11 — 9\nНесколько раз в неделю — 34 — 25 — 14\nНесколько раз в месяц — 21 — 22 — 15\nНе занимаюсь — 25 — 42 — 62' + SEL +
      '1) Среди граждан 45 лет и старше большинство занимаются спортом хотя бы несколько раз в месяц.\n2) Доля не занимающихся спортом растёт с возрастом.\n3) Доля занимающихся спортом несколько раз в месяц практически одинакова во всех группах.\n4) Большинство молодых людей 18–24 лет занимаются спортом не реже нескольких раз в неделю.\n5) В группе 25–44 лет не занимаются спортом менее половины опрошенных.',
      a: '245', s: ['1) 9 + 14 + 15 = 38%: неверно.', '2) 25 → 42 → 62: верно.', '3) 21, 22 и 15 — в старшей группе заметно меньше: неверно.', '4) 20 + 34 = 54% > 50%: верно.', '5) 42% < 50%: верно.'] },
    { q: 'В 2015 и 2025 гг. граждан страны Z спрашивали: «Какие качества вы считаете наиболее важными для политического лидера?» (можно было выбрать не более трёх вариантов). Результаты опроса (в % от числа опрошенных) представлены в таблице.\nКачество — 2015 г. — 2025 г.\nЧестность — 58 — 61\nКомпетентность — 40 — 52\nРешительность — 45 — 38\nЗабота о людях — 50 — 55\nХаризма — 22 — 14' + SEL +
      '1) В 2025 г. компетентность называли чаще, чем заботу о людях.\n2) Честность в оба года называли чаще всех остальных качеств.\n3) В 2025 г. большинство опрошенных назвали компетентность важным качеством лидера.\n4) Харизму в 2025 г. назвали вдвое меньше опрошенных, чем в 2015 г.\n5) За десять лет доли назвавших решительность и харизму снизились.',
      a: '235', s: ['1) 52 < 55: неверно.', '2) 58 и 61 — максимумы в своих столбцах: верно.', '3) 52% > 50%: верно.', '4) 22 → 14, а половина от 22 — 11: неверно.', '5) 45 → 38 и 22 → 14: верно.'] }
  ],
  10: [
    { q: 'Выберите верные суждения о политической власти и запишите цифры, под которыми они указаны.\n1) Власть — способность и возможность оказывать определяющее воздействие на деятельность и поведение людей.\n2) Власть существует только в государственно организованном обществе.\n3) К ресурсам власти относятся экономические, силовые, информационные ресурсы.\n4) Легитимность власти означает признание её населением правомерной.\n5) Политическая власть осуществляется исключительно путём принуждения.',
      a: '134', s: ['2 — неверно: власть существует и в семье, и в догосударственном обществе.', '5 — неверно: власть опирается также на убеждение, авторитет, поощрение.', '1, 3, 4 — верно.'] },
    { q: 'Выберите верные суждения о государстве и его признаках и запишите цифры, под которыми они указаны.\n1) Государство возникло одновременно с появлением человеческого общества.\n2) Суверенитет означает верховенство государственной власти внутри страны и её независимость во внешних отношениях.\n3) Только государство вправе издавать законы, обязательные для всего населения страны.\n4) Сбор налогов не является признаком государства.\n5) Государство обладает монополией на легальное применение принуждения.',
      a: '235', s: ['1 — неверно: государство возникло на определённом этапе развития общества.', '4 — неверно: взимание налогов и сборов — признак государства.', '2, 3, 5 — верно.'] },
    { q: 'Выберите верные суждения об избирательных системах и запишите цифры, под которыми они указаны.\n1) При мажоритарной системе побеждает кандидат, набравший большинство голосов в избирательном округе.\n2) При пропорциональной системе избиратели голосуют за списки кандидатов от партий.\n3) Пропорциональная избирательная система исключает установление проходного барьера.\n4) Абсентеизм — уклонение избирателей от участия в голосовании.\n5) Смешанная избирательная система сочетает элементы мажоритарной и пропорциональной систем.',
      a: '1245', s: ['3 — неверно: при пропорциональной системе часто устанавливается заградительный (проходной) барьер.', '1, 2, 4, 5 — верно.'] },
    { q: 'Выберите верные суждения о политической системе общества и запишите цифры, под которыми они указаны.\n1) Политические партии не входят в политическую систему общества.\n2) Центральным элементом институциональной подсистемы является государство.\n3) Политическая система не взаимодействует с другими сферами жизни общества.\n4) Политические нормы регулируют отношения по поводу власти.\n5) В политической системе выделяют институциональную, нормативную, коммуникативную и культурно-идеологическую подсистемы.',
      a: '245', s: ['1 — неверно: партии — элемент институциональной подсистемы.', '3 — неверно: политика тесно связана с экономикой, социальной и духовной сферами.', '2, 4, 5 — верно.'] },
    { q: 'Выберите верные суждения о правовом государстве и гражданском обществе и запишите цифры, под которыми они указаны.\n1) В правовом государстве органы власти не связаны законами.\n2) Правовое государство основано на верховенстве закона.\n3) Институты гражданского общества создаются по решению органов государственной власти.\n4) Принцип разделения властей предполагает выделение законодательной, исполнительной и судебной властей.\n5) Гражданское общество — сфера самопроявления свободных граждан и добровольно сформированных объединений, независимая от прямого вмешательства государства.',
      a: '245', s: ['1 — неверно: в правовом государстве закон связывает и государство, и граждан.', '3 — неверно: институты гражданского общества создаются по инициативе самих граждан.', '2, 4, 5 — верно.'] },
    { q: 'Выберите верные суждения о политическом участии и запишите цифры, под которыми они указаны.\n1) Политическое участие — вовлечённость граждан в политический процесс.\n2) Абсентеизм — активное участие граждан в выборах.\n3) Голосование на выборах — одна из форм политического участия.\n4) Протестные акции не являются формой политического участия.\n5) Политическое участие может быть индивидуальным и коллективным.',
      a: '135', s: ['2 — неверно: абсентеизм — уклонение от участия в выборах.', '4 — неверно: митинги и демонстрации — формы (неконвенционального) политического участия.', '1, 3, 5 — верно.'] },
    { q: 'Выберите верные суждения о политической элите и политическом лидерстве и запишите цифры, под которыми они указаны.\n1) Политическая элита — относительно небольшая группа, занимающая ведущие позиции в органах власти и участвующая в принятии важнейших решений.\n2) Согласно М. Веберу, харизматическое лидерство основано на вере в исключительные качества лидера.\n3) Традиционное лидерство основано на вере в святость обычаев и традиций.\n4) Рационально-легальное лидерство основано на личной преданности вождю.\n5) Политическая элита существует только при демократическом политическом режиме.',
      a: '123', s: ['4 — неверно: рационально-легальное лидерство опирается на законные процедуры и правила, а не на личную преданность.', '5 — неверно: политическая элита есть при любом режиме.', '1, 2, 3 — верно.'] },
    { q: 'Выберите верные суждения о политической идеологии и запишите цифры, под которыми они указаны.\n1) Консерватизм выступает за быстрые радикальные преобразования общества.\n2) Политическая идеология — система идей, выражающих интересы определённых социальных групп.\n3) Либерализм ставит во главу угла свободу личности и неприкосновенность частной собственности.\n4) Согласно Конституции РФ, в России устанавливается обязательная государственная идеология.\n5) Социал-демократия выступает за социальную справедливость и активную социальную политику государства.',
      a: '235', s: ['1 — неверно: консерватизм ориентирован на сохранение традиций и постепенные изменения.', '4 — неверно: ст. 13 Конституции РФ признаёт идеологическое многообразие.', '2, 3, 5 — верно.'] },
    { q: 'Выберите верные суждения о демократии и запишите цифры, под которыми они указаны.\n1) Демократия предполагает признание народа источником власти.\n2) При демократии решения принимаются большинством с учётом прав меньшинства.\n3) Непосредственная демократия — прямое участие граждан в принятии решений, например на референдуме.\n4) При демократии отсутствует политическая оппозиция.\n5) Представительная демократия осуществляется через выборных представителей народа.',
      a: '1235', s: ['4 — неверно: легальная оппозиция — признак демократии.', '1, 2, 3, 5 — верно.'] }
  ],
  11: [
    { q: 'Установите соответствие между характеристиками и избирательными системами: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nХАРАКТЕРИСТИКИ\nА) голосование за списки кандидатов от партий\nБ) в каждом избирательном округе избирается один депутат\nВ) мандаты распределяются пропорционально числу голосов, полученных партиями\nГ) для победы в первом туре кандидату может потребоваться абсолютное большинство голосов\nД) часто устанавливается заградительный барьер для партий\n\nИЗБИРАТЕЛЬНЫЕ СИСТЕМЫ\n1) мажоритарная\n2) пропорциональная',
      a: '21212', cols: ['Характеристики', 'Избирательные системы'], s: ['Мажоритарная (1): одномандатные округа, побеждает кандидат, набравший большинство (Б, Г).', 'Пропорциональная (2): партийные списки, распределение мандатов по доле голосов, барьер (А, В, Д).'] },
    { q: 'Установите соответствие между характеристиками и типами легитимности власти (по М. Веберу): к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nХАРАКТЕРИСТИКИ\nА) власть основана на вере в исключительные личные качества лидера\nБ) власть передаётся по наследству в соответствии с обычаями\nВ) власть признаётся, поскольку сформирована по законным процедурам\nГ) подчинение основано на привычке и уважении к старине\nД) граждане подчиняются не конкретной личности, а должности и закону\n\nТИПЫ ЛЕГИТИМНОСТИ\n1) традиционный\n2) харизматический\n3) рационально-легальный',
      a: '21313', cols: ['Характеристики', 'Типы легитимности'], s: ['Традиционный (1): обычай, наследование, привычка (Б, Г).', 'Харизматический (2): вера в особые качества лидера (А).', 'Рационально-легальный (3): закон, процедуры, подчинение должности (В, Д).'] },
    { q: 'Установите соответствие между положениями и политическими идеологиями: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛОЖЕНИЯ\nА) приоритет свободы личности и минимальное вмешательство государства в экономику\nБ) стремление сохранить традиционные ценности и устои общества\nВ) государство должно перераспределять доходы ради социальной справедливости\nГ) признание естественных прав человека, данных ему от рождения\nД) предпочтение постепенных изменений и осторожное отношение к реформам\n\nИДЕОЛОГИИ\n1) либерализм\n2) консерватизм\n3) социал-демократия',
      a: '12312', cols: ['Положения', 'Идеологии'], s: ['Либерализм (1): свобода личности, естественные права, рынок (А, Г).', 'Консерватизм (2): традиции, постепенность (Б, Д).', 'Социал-демократия (3): социальная справедливость, перераспределение (В).'] },
    { q: 'Установите соответствие между признаками и типами политических партий (по организационному устройству): к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИЗНАКИ\nА) небольшое число членов, ядро составляют профессиональные политики\nБ) фиксированное членство и регулярная уплата членских взносов\nВ) активизация деятельности преимущественно в период выборов\nГ) финансирование главным образом за счёт взносов членов партии\nД) опора на известных политиков и крупных спонсоров\n\nТИПЫ ПАРТИЙ\n1) кадровая\n2) массовая',
      a: '12121', cols: ['Признаки', 'Типы партий'], s: ['Кадровые (1): немногочисленны, опираются на профессиональных политиков и спонсоров, активны в период выборов (А, В, Д).', 'Массовые (2): многочисленное фиксированное членство, взносы (Б, Г).'] },
    { q: 'Установите соответствие между примерами и функциями государства: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИМЕРЫ\nА) защита государственных границ\nБ) развитие системы здравоохранения\nВ) участие в деятельности международных организаций\nГ) охрана общественного порядка\nД) поддержка малого предпринимательства\n\nФУНКЦИИ\n1) внутренние\n2) внешние',
      a: '21211', cols: ['Примеры', 'Функции государства'], s: ['Внешние функции (2) связаны с отношениями с другими государствами: оборона и защита границ (А), международное сотрудничество (В).', 'Внутренние функции (1): социальная (Б), правоохранительная (Г), экономическая (Д).'] },
    { q: 'Установите соответствие между признаками и формами государственно-территориального устройства: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИЗНАКИ\nА) единая система высших органов власти, административно-территориальные единицы не обладают политической самостоятельностью\nБ) составные части имеют собственные конституции (уставы) и законодательство\nВ) двухпалатный парламент, одна из палат представляет интересы составных частей\nГ) единая конституция для всей страны, составные части не имеют своих конституций\nД) разграничение предметов ведения между центром и составными частями\n\nФОРМЫ УСТРОЙСТВА\n1) унитарное государство\n2) федерация',
      a: '12212', cols: ['Признаки', 'Формы устройства'], s: ['Унитарное государство (1): единая конституция и единая система органов, части несамостоятельны (А, Г).', 'Федерация (2): у субъектов свои конституции/уставы и законы, палата субъектов, разграничение предметов ведения (Б, В, Д).'] },
    { q: 'Установите соответствие между признаками и формами правления: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИЗНАКИ\nА) правительство формируется парламентом и ответственно перед ним\nБ) президент избирается всенародно и сам возглавляет исполнительную власть\nВ) пост премьер-министра отсутствует, главой правительства является президент\nГ) президент избирается парламентом и выполняет преимущественно представительские функции\nД) вотум недоверия парламента влечёт отставку правительства\n\nФОРМЫ ПРАВЛЕНИЯ\n1) президентская республика\n2) парламентская республика',
      a: '21122', cols: ['Признаки', 'Формы правления'], s: ['Президентская республика (1): президент — глава государства и исполнительной власти, премьера нет (Б, В).', 'Парламентская республика (2): правительство формирует и контролирует парламент, президент избирается парламентом и имеет в основном представительские функции (А, Г, Д).'] },
    { q: 'Установите соответствие между признаками и общественными институтами: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИЗНАКИ\nА) добровольные объединения граждан по интересам\nБ) обладание суверенитетом\nВ) общественный контроль за деятельностью органов власти\nГ) установление и взимание налогов\nД) издание обязательных для всех нормативных правовых актов\n\nИНСТИТУТЫ\n1) гражданское общество\n2) государство',
      a: '12122', cols: ['Признаки', 'Институты'], s: ['Гражданское общество (1): добровольные объединения, общественный контроль над властью (А, В).', 'Государство (2): суверенитет, налоги, общеобязательные нормативные акты (Б, Г, Д).'] },
    { q: 'Установите соответствие между характеристиками и типами политической культуры (по Г. Алмонду и С. Вербе): к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nХАРАКТЕРИСТИКИ\nА) отсутствие интереса к политической системе общества, ориентация на местные интересы\nБ) граждане осознают влияние власти на свою жизнь, но пассивны и ориентированы на подчинение\nВ) граждане активно участвуют в политике и стремятся влиять на принятие решений\nГ) ожидание благ от власти при отсутствии стремления участвовать в политике\nД) ориентация на традиции, местных лидеров и вождей общин\n\nТИПЫ ПОЛИТИЧЕСКОЙ КУЛЬТУРЫ\n1) патриархальная\n2) подданническая\n3) активистская (культура участия)',
      a: '12321', cols: ['Характеристики', 'Типы политической культуры'], s: ['Патриархальная (1): нет представлений о политической системе, ориентация на местное и традиционное (А, Д).', 'Подданническая (2): власть замечают, но остаются пассивными (Б, Г).', 'Активистская (3): активное участие в политике (В).'] }
  ],
  12: [
    { q: 'В государстве Z глава государства — президент, избираемый гражданами на прямых выборах. Президент возглавляет правительство, должность премьер-министра отсутствует. Страна состоит из штатов, каждый из которых имеет собственную конституцию и законодательный орган. Выборы проводятся на альтернативной основе, оппозиционные партии действуют свободно. Выберите верные характеристики государства Z и запишите цифры, под которыми они указаны.\n1) парламентская республика\n2) президентская республика\n3) федеративное государство\n4) унитарное государство\n5) демократический политический режим\n6) тоталитарный политический режим',
      a: '235', s: ['Президент избирается народом и возглавляет правительство — президентская республика (2).', 'Штаты с собственными конституциями — федерация (3).', 'Альтернативные выборы и свобода оппозиции — демократия (5).'] },
    { q: 'Государство Z является республикой. Какие дополнительные сведения позволят сделать вывод о том, что Z — парламентская республика? Запишите цифры, под которыми они указаны.\n1) Правительство формируется парламентом по итогам выборов и несёт ответственность перед ним.\n2) Президент избирается всенародно и лично руководит правительством.\n3) Глава государства избирается парламентом и выполняет преимущественно представительские функции.\n4) Парламент страны состоит из двух палат.\n5) Парламент может выразить недоверие правительству, что влечёт его отставку.\n6) В стране действует многопартийная система.',
      a: '135', s: ['1, 3, 5 — признаки парламентской республики.', '2 — признак президентской республики.', '4, 6 — встречаются при любой форме правления и не позволяют сделать вывод.'] },
    { q: 'Какие сведения о государстве Z свидетельствуют о том, что оно является унитарным? Запишите цифры, под которыми они указаны.\n1) Административно-территориальные единицы не обладают политической самостоятельностью.\n2) На всей территории действует единая конституция, территориальные единицы не имеют собственных конституций.\n3) Составные части государства имеют собственные законодательные органы и конституции.\n4) Глава государства избирается всенародно.\n5) Существует единая система высших органов государственной власти для всей страны.\n6) Предметы ведения разграничены между центром и субъектами.',
      a: '125', s: ['1, 2, 5 — признаки унитарного государства.', '3, 6 — признаки федерации.', '4 — характеристика формы правления, а не территориального устройства.'] },
    { q: 'В государстве Z власть передаётся по наследству. Монарх единолично издаёт законы, назначает и смещает министров, является верховным судьёй; парламента в стране нет. Деятельность политических партий запрещена, свобода слова ограничена, однако частная жизнь граждан и экономика государством не контролируются. Выберите верные характеристики государства Z и запишите цифры, под которыми они указаны.\n1) абсолютная монархия\n2) парламентская монархия\n3) авторитарный политический режим\n4) тоталитарный политический режим\n5) отсутствие разделения властей\n6) республика',
      a: '135', s: ['Монарх обладает всей полнотой власти, парламента нет — абсолютная монархия (1), разделения властей нет (5).', 'Ограничены политические свободы, но частная жизнь и экономика не контролируются — авторитарный, а не тоталитарный режим (3).'] },
    { q: 'В государстве Z президент избирается гражданами на всеобщих выборах. Председатель правительства назначается президентом с согласия парламента; правительство несёт ответственность как перед президентом, так и перед парламентом. Выберите верные характеристики государства Z и запишите цифры, под которыми они указаны.\n1) смешанная (полупрезидентская) республика\n2) абсолютная монархия\n3) глава государства — президент\n4) парламентская монархия\n5) правительство несёт двойную ответственность\n6) президент избирается парламентом',
      a: '135', s: ['Есть выборный президент — это республика (3), монархии исключаются (2, 4).', 'Двойная ответственность правительства (5) — признак смешанной республики (1).', '6 — неверно: президент избирается гражданами.'] },
    { q: 'Какие сведения о государстве Z позволяют сделать вывод о том, что в нём установлен демократический политический режим? Запишите цифры, под которыми они указаны.\n1) Регулярно проводятся свободные альтернативные выборы.\n2) Действует принцип разделения властей, суды независимы.\n3) Средства массовой информации подвергаются цензуре.\n4) Существует единая обязательная для всех идеология.\n5) Легально действуют оппозиционные партии.\n6) Глава государства пожизненно назначается правящей партией.',
      a: '125', s: ['1, 2, 5 — признаки демократии.', '3, 4, 6 — признаки недемократических режимов.'] },
    { q: 'В государстве Z существует единственная правящая партия. Выберите сведения, указывающие на то, что в Z установлен тоталитарный политический режим, и запишите цифры, под которыми они указаны.\n1) Государство контролирует все сферы жизни общества, включая частную жизнь граждан.\n2) Существует единая официальная идеология, обязательная для всех.\n3) Действуют независимые от государства профсоюзы.\n4) Насаждается культ личности вождя.\n5) Регулярно проводятся альтернативные многопартийные выборы.\n6) Применяются массовые репрессии против инакомыслящих.',
      a: '1246', s: ['1, 2, 4, 6 — признаки тоталитаризма.', '3, 5 — признаки гражданского общества и демократии, при тоталитаризме невозможны.'] },
    { q: 'В государстве Z глава государства — монарх, получивший власть по наследству. Законы принимает избираемый парламент, однако монарх может наложить на них абсолютное вето. Монарх сам формирует правительство, которое ответственно только перед ним. Выберите верные характеристики государства Z и запишите цифры, под которыми они указаны.\n1) дуалистическая монархия\n2) парламентская монархия\n3) ограниченная монархия\n4) абсолютная монархия\n5) правительство ответственно перед монархом\n6) президентская республика',
      a: '135', s: ['Есть парламент, ограничивающий власть монарха, — монархия ограниченная (3), а не абсолютная (4).', 'Монарх формирует правительство и обладает абсолютным вето — дуалистическая монархия (1, 5), а не парламентская (2).'] },
    { q: 'В государстве Z монарх «царствует, но не правит»: правительство формирует партия, победившая на выборах в парламент, и оно ответственно перед парламентом. Страна делится на графства, которые не обладают суверенитетом и собственным законодательством. Выберите верные характеристики государства Z и запишите цифры, под которыми они указаны.\n1) парламентская монархия\n2) унитарное государство\n3) абсолютная монархия\n4) федерация\n5) правительство ответственно перед парламентом\n6) конфедерация',
      a: '125', s: ['Монарх с номинальной властью, правительство ответственно перед парламентом — парламентская монархия (1, 5).', 'Графства без собственного законодательства — унитарное государство (2).'] }
  ],
  13: [
    { q: 'Выберите верные положения о Президенте Российской Федерации, закреплённые в Конституции РФ, и запишите цифры, под которыми они указаны.\n1) Президентом РФ может быть избран гражданин РФ не моложе 35 лет, постоянно проживающий в РФ не менее 25 лет.\n2) Одно и то же лицо не может занимать должность Президента РФ более двух сроков.\n3) Президент РФ является Председателем Правительства РФ.\n4) Президент РФ является Верховным Главнокомандующим Вооружёнными Силами РФ.\n5) Президент РФ избирается Федеральным Собранием.',
      a: '124', s: ['1, 2 — ст. 81 (с поправками 2020 г.); 4 — ст. 87: верно.', '3 — неверно: Председатель Правительства назначается Президентом.', '5 — неверно: Президент избирается гражданами на основе всеобщего равного и прямого избирательного права при тайном голосовании.'] },
    { q: 'Выберите положения, закреплённые в главе 2 «Права и свободы человека и гражданина» Конституции РФ, и запишите цифры, под которыми они указаны.\n1) Каждый имеет право на свободу и личную неприкосновенность.\n2) Арест, заключение под стражу и содержание под стражей допускаются только по судебному решению.\n3) Основное общее образование обязательно.\n4) Каждый гражданин имеет право бесплатно получить высшее образование в любом вузе без конкурса.\n5) Каждый обязан сохранять природу и окружающую среду.',
      a: '1235', s: ['1, 2 — ст. 22; 3 — ст. 43; 5 — ст. 58: верно.', '4 — неверно: бесплатное высшее образование гарантируется на конкурсной основе.'] },
    { q: 'Выберите обязанности, которые Конституция РФ возлагает на граждан (каждого), и запишите цифры, под которыми они указаны.\n1) платить законно установленные налоги и сборы\n2) защищать Отечество\n3) участвовать в выборах\n4) заботиться о сохранении исторического и культурного наследия, беречь памятники истории и культуры\n5) состоять в политической партии\n6) получить высшее образование',
      a: '124', s: ['1 — ст. 57, 2 — ст. 59, 4 — ст. 44: обязанности.', '3 — участие в выборах является правом, а не обязанностью.', '5, 6 — не являются обязанностями.'] },
    { q: 'Выберите положения, относящиеся к основам конституционного строя РФ, и запишите цифры, под которыми они указаны.\n1) Носителем суверенитета и единственным источником власти в РФ является её многонациональный народ.\n2) В РФ признаётся идеологическое многообразие.\n3) Органы местного самоуправления входят в систему органов государственной власти.\n4) Государственная власть осуществляется на основе разделения на законодательную, исполнительную и судебную.\n5) Никакая идеология не может устанавливаться в качестве государственной или обязательной.\n6) В РФ признаётся и защищается только государственная собственность.',
      a: '1245', s: ['1 — ст. 3; 2, 5 — ст. 13; 4 — ст. 10: верно.', '3 — неверно: по ст. 12 органы местного самоуправления не входят в систему органов государственной власти.', '6 — неверно: по ст. 8 равным образом признаются и защищаются частная, государственная, муниципальная и иные формы собственности.'] },
    { q: 'Выберите верные положения о Федеральном Собрании РФ, закреплённые в Конституции РФ, и запишите цифры, под которыми они указаны.\n1) Федеральное Собрание — парламент РФ — является представительным и законодательным органом.\n2) Федеральное Собрание состоит из двух палат — Совета Федерации и Государственной Думы.\n3) Депутатом Государственной Думы может быть избран гражданин РФ, достигший 21 года.\n4) Государственная Дума избирается сроком на четыре года.\n5) Одно и то же лицо может одновременно быть членом Совета Федерации и депутатом Государственной Думы.',
      a: '123', s: ['1 — ст. 94, 2 — ст. 95, 3 — ст. 97: верно.', '4 — неверно: Государственная Дума избирается на пять лет (ст. 96).', '5 — неверно: совмещение запрещено (ст. 97).'] },
    { q: 'Выберите вопросы, которые по Конституции РФ находятся в ведении Российской Федерации (а не в совместном ведении РФ и её субъектов), и запишите цифры, под которыми они указаны.\n1) федеральный бюджет\n2) оборона и безопасность\n3) защита семьи, материнства, отцовства и детства\n4) гражданство в Российской Федерации\n5) трудовое законодательство\n6) установление общих принципов налогообложения',
      a: '124', s: ['1, 2, 4 — ведение РФ (ст. 71).', '3, 5, 6 — совместное ведение РФ и субъектов (ст. 72).'] },
    { q: 'Выберите вопросы, которые по Конституции РФ находятся в совместном ведении Российской Федерации и её субъектов, и запишите цифры, под которыми они указаны.\n1) административное, семейное, трудовое законодательство\n2) общие вопросы воспитания и образования\n3) внешняя политика и международные отношения\n4) природопользование и охрана окружающей среды\n5) денежная эмиссия\n6) уголовное законодательство',
      a: '124', s: ['1, 2, 4 — совместное ведение (ст. 72).', '3, 5, 6 — ведение Российской Федерации (ст. 71).'] },
    { q: 'Выберите верные положения о Правительстве РФ, закреплённые в Конституции РФ, и запишите цифры, под которыми они указаны.\n1) Правительство РФ осуществляет исполнительную власть.\n2) Председатель Правительства РФ назначается Президентом РФ после утверждения его кандидатуры Государственной Думой.\n3) Правительство РФ разрабатывает и представляет Государственной Думе федеральный бюджет.\n4) Правительство РФ принимает федеральные законы.\n5) Правительство РФ издаёт постановления и распоряжения.',
      a: '1235', s: ['1 — ст. 110, 2 — ст. 111, 3 — ст. 114, 5 — ст. 115: верно.', '4 — неверно: федеральные законы принимает Государственная Дума.'] },
    { q: 'Выберите верные положения о судебной власти в РФ, закреплённые в Конституции РФ, и запишите цифры, под которыми они указаны.\n1) Правосудие в РФ осуществляется только судом.\n2) Судьи независимы и подчиняются только Конституции РФ и федеральному закону.\n3) Создание чрезвычайных судов допускается в период военного положения.\n4) Конституционный Суд РФ состоит из 11 судей.\n5) Разбирательство дел во всех судах всегда закрытое.\n6) Судьи несменяемы.',
      a: '1246', s: ['1 — ст. 118, 2 — ст. 120, 4 — ст. 125 (с поправками 2020 г.), 6 — ст. 121: верно.', '3 — неверно: создание чрезвычайных судов не допускается.', '5 — неверно: разбирательство дел во всех судах открытое, закрытое — только в случаях, предусмотренных законом (ст. 123).'] }
  ],
  14: [
    { q: 'Установите соответствие между полномочиями и органами государственной власти РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) обеспечение проведения единой финансовой, кредитной и денежной политики\nБ) осуществление помилования\nВ) управление федеральной собственностью\nГ) решение вопросов гражданства РФ и предоставления политического убежища\nД) награждение государственными наградами РФ\n\nОРГАНЫ ВЛАСТИ\n1) Президент РФ\n2) Правительство РФ',
      a: '21211', cols: ['Полномочия', 'Органы власти'], s: ['Правительство (2): финансовая, кредитная, денежная политика; управление федеральной собственностью (ст. 114).', 'Президент (1): помилование, гражданство и убежище, государственные награды (ст. 89).'] },
    { q: 'Установите соответствие между полномочиями и органами государственной власти РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) объявление амнистии\nБ) утверждение указа Президента РФ о введении чрезвычайного положения\nВ) подписание и обнародование федеральных законов\nГ) отрешение Президента РФ от должности\nД) выдвижение обвинения против Президента РФ для отрешения его от должности\n\nОРГАНЫ ВЛАСТИ\n1) Государственная Дума\n2) Совет Федерации\n3) Президент РФ',
      a: '12321', cols: ['Полномочия', 'Органы власти'], s: ['Госдума (1): амнистия, выдвижение обвинения против Президента (ст. 103).', 'Совет Федерации (2): утверждение указа о чрезвычайном положении, отрешение Президента от должности (ст. 102).', 'Президент (3): подписывает и обнародует федеральные законы (ст. 84).'] },
    { q: 'Установите соответствие между полномочиями и органами государственной власти РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) назначение выборов в Государственную Думу\nБ) назначение на должность и освобождение от должности Уполномоченного по правам человека\nВ) осуществление мер по обеспечению обороны страны\nГ) определение основных направлений внутренней и внешней политики государства\nД) назначение на должность и освобождение от должности Председателя Центрального банка РФ\n\nОРГАНЫ ВЛАСТИ\n1) Президент РФ\n2) Государственная Дума\n3) Правительство РФ',
      a: '12312', cols: ['Полномочия', 'Органы власти'], s: ['Президент (1): назначает выборы в Госдуму, определяет основные направления политики (ст. 80, 84).', 'Госдума (2): Уполномоченный по правам человека, Председатель ЦБ (ст. 103).', 'Правительство (3): меры по обеспечению обороны (ст. 114).'] },
    { q: 'Установите соответствие между полномочиями и судами РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) разрешение дел о соответствии Конституции РФ федеральных законов\nБ) толкование Конституции РФ\nВ) рассмотрение в качестве высшего судебного органа гражданских, уголовных, административных дел и экономических споров\nГ) проверка конституционности законов по жалобам на нарушение конституционных прав граждан\nД) судебный надзор за деятельностью судов общей юрисдикции и арбитражных судов\n\nСУДЫ\n1) Конституционный Суд РФ\n2) Верховный Суд РФ',
      a: '11212', cols: ['Полномочия', 'Суды'], s: ['Конституционный Суд (1): проверка конституционности законов, в том числе по жалобам граждан, толкование Конституции (ст. 125).', 'Верховный Суд (2): высший суд по гражданским, уголовным, административным делам и экономическим спорам, надзор за нижестоящими судами (ст. 126).'] },
    { q: 'Установите соответствие между полномочиями и органами государственной власти РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) разработка федерального бюджета и обеспечение его исполнения\nБ) решение вопроса о возможности использования Вооружённых Сил РФ за пределами территории РФ\nВ) назначение выборов Президента РФ\nГ) обеспечение проведения единой социально ориентированной государственной политики в области культуры, науки, образования\nД) назначение на должность судей Конституционного Суда РФ\n\nОРГАНЫ ВЛАСТИ\n1) Совет Федерации\n2) Правительство РФ',
      a: '21121', cols: ['Полномочия', 'Органы власти'], s: ['Правительство (2): бюджет, социальная политика в области культуры, науки, образования (ст. 114).', 'Совет Федерации (1): использование армии за рубежом, назначение выборов Президента, назначение судей КС по представлению Президента (ст. 102).'] },
    { q: 'Установите соответствие между полномочиями и органами государственной власти РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) формирование Совета Безопасности РФ и руководство им\nБ) утверждение изменения границ между субъектами РФ\nВ) утверждение военной доктрины РФ\nГ) утверждение указа Президента РФ о введении военного положения\nД) присвоение высших воинских и высших специальных званий\n\nОРГАНЫ ВЛАСТИ\n1) Президент РФ\n2) Совет Федерации',
      a: '12121', cols: ['Полномочия', 'Органы власти'], s: ['Президент (1): Совет Безопасности, военная доктрина (ст. 83), высшие воинские звания (ст. 89).', 'Совет Федерации (2): изменение границ между субъектами, утверждение указа о военном положении (ст. 102).'] },
    { q: 'Установите соответствие между полномочиями и органами государственной власти РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) решение вопроса о доверии Правительству РФ\nБ) заслушивание ежегодных отчётов Правительства РФ о результатах его деятельности\nВ) роспуск Государственной Думы в случаях, предусмотренных Конституцией РФ\nГ) обращение к Федеральному Собранию с ежегодными посланиями\nД) представление Государственной Думе кандидатуры для назначения на должность Председателя Центрального банка РФ\n\nОРГАНЫ ВЛАСТИ\n1) Президент РФ\n2) Государственная Дума',
      a: '22111', cols: ['Полномочия', 'Органы власти'], s: ['Госдума (2): вопрос о доверии Правительству, отчёты Правительства (ст. 103).', 'Президент (1): роспуск Думы, послания, представление кандидатуры Председателя ЦБ (ст. 83, 84).'] },
    { q: 'Установите соответствие между полномочиями и органами государственной власти РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) назначение референдума\nБ) утверждение по представлению Председателя Правительства кандидатур заместителей Председателя Правительства и федеральных министров (за исключением указанных в Конституции)\nВ) назначение на должность судей Верховного Суда РФ\nГ) представление Совету Федерации кандидатур для назначения на должность судей Конституционного Суда РФ\nД) назначение и освобождение полномочных представителей Президента РФ\n\nОРГАНЫ ВЛАСТИ\n1) Президент РФ\n2) Государственная Дума\n3) Совет Федерации',
      a: '12311', cols: ['Полномочия', 'Органы власти'], s: ['Президент (1): назначает референдум, представляет кандидатуры судей, назначает полпредов (ст. 83, 84).', 'Госдума (2): утверждает кандидатуры вице-премьеров и министров (ст. 103, 112).', 'Совет Федерации (3): назначает судей Верховного Суда по представлению Президента (ст. 102).'] },
    { q: 'Установите соответствие между полномочиями и органами государственной власти РФ: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПОЛНОМОЧИЯ\nА) объявление амнистии\nБ) осуществление мер по обеспечению законности, прав и свобод граждан, борьбе с преступностью\nВ) утверждение изменения границ между субъектами РФ\nГ) заслушивание ежегодных отчётов Правительства РФ\nД) обеспечение проведения единой государственной политики в области экологии\n\nОРГАНЫ ВЛАСТИ\n1) Правительство РФ\n2) Государственная Дума\n3) Совет Федерации',
      a: '21321', cols: ['Полномочия', 'Органы власти'], s: ['Правительство (1): законность и борьба с преступностью, экологическая политика (ст. 114).', 'Госдума (2): амнистия, отчёты Правительства (ст. 103).', 'Совет Федерации (3): изменение границ между субъектами (ст. 102).'] }
  ],
  15: [
    { q: 'Гражданке Н. 17 лет. Она и её молодой человек, которому 19 лет, хотят вступить в брак. Выберите верные утверждения и запишите цифры, под которыми они указаны.\n1) Брачный возраст в РФ по общему правилу составляет 18 лет.\n2) При наличии уважительных причин органы местного самоуправления по месту жительства вправе по просьбе Н. разрешить ей вступить в брак.\n3) Брак заключается в органах записи актов гражданского состояния (ЗАГС).\n4) Для заключения брака Н. обязательно требуется письменное согласие родителей.\n5) Брак в любом случае может быть заключён в день подачи заявления.',
      a: '123', s: ['1, 2 — ст. 13 Семейного кодекса РФ: брачный возраст 18 лет, снижение до 16 лет органами местного самоуправления при уважительных причинах.', '3 — ст. 10 СК РФ: верно.', '4 — неверно: согласие родителей законом не требуется.', '5 — неверно: по общему правилу брак заключается по истечении месяца со дня подачи заявления.'] },
    { q: 'Сергей (20 лет) окончил колледж по программе, имеющей государственную аккредитацию, и через три месяца впервые устраивается на работу по полученной специальности. Выберите верные утверждения и запишите цифры, под которыми они указаны.\n1) Испытание при приёме на работу Сергею не может быть установлено.\n2) Трудовой договор с Сергеем заключается в письменной форме.\n3) Ежегодный основной оплачиваемый отпуск Сергея составит не менее 28 календарных дней.\n4) Работодатель вправе установить Сергею нормальную продолжительность рабочего времени 50 часов в неделю.\n5) Сергей может расторгнуть трудовой договор по собственному желанию, предупредив работодателя не позднее чем за две недели.',
      a: '1235', s: ['1 — ст. 70 ТК РФ: испытание не устанавливается для впервые поступающих на работу по специальности в течение года после окончания обучения.', '2 — ст. 67, 3 — ст. 115, 5 — ст. 80 ТК РФ: верно.', '4 — неверно: нормальная продолжительность рабочего времени — не более 40 часов в неделю.'] },
    { q: 'Пятнадцатилетний Игорь подрабатывает курьером и получает заработную плату. Выберите верные утверждения о его гражданской дееспособности и запишите цифры, под которыми они указаны.\n1) Игорь вправе самостоятельно распоряжаться своим заработком.\n2) Игорь может самостоятельно совершать мелкие бытовые сделки.\n3) Игорь вправе без согласия родителей продать принадлежащую ему квартиру.\n4) Игорь может самостоятельно вносить вклады в кредитные организации и распоряжаться ими.\n5) Игорь обладает гражданской дееспособностью в полном объёме.',
      a: '124', s: ['По ст. 26 ГК РФ несовершеннолетние от 14 до 18 лет самостоятельно распоряжаются заработком, вносят вклады и распоряжаются ими, совершают мелкие бытовые сделки (1, 2, 4).', '3 — неверно: для такой сделки нужно согласие родителей (и органа опеки).', '5 — неверно: в полном объёме дееспособность возникает с 18 лет (или при эмансипации, браке).'] },
    { q: 'Анна купила в магазине свитер, но дома поняла, что он не подходит ей по расцветке. Свитер не был в употреблении, ярлыки сохранены, кассовый чек есть, с момента покупки прошло 5 дней. Выберите верные утверждения и запишите цифры, под которыми они указаны.\n1) Анна вправе обменять свитер на аналогичный товар другой расцветки.\n2) Если аналогичного товара нет в продаже, Анна вправе вернуть свитер и получить уплаченные деньги.\n3) Обменять свитер можно было только в течение трёх дней с момента покупки.\n4) Магазин обязан принять товар обратно только при наличии в нём брака.\n5) Отношения Анны и магазина регулируются законодательством о защите прав потребителей.',
      a: '125', s: ['По ст. 25 Закона «О защите прав потребителей» непродовольственный товар надлежащего качества, не подошедший по расцветке, можно обменять в течение 14 дней (не считая дня покупки) (1, 2 — верно, 3 — неверно).', '4 — неверно: обмен возможен и для товара надлежащего качества.', '5 — верно.'] },
    { q: 'Шестнадцатилетний Павел совершил мелкое хулиганство — нецензурно бранился в общественном месте. Выберите верные утверждения и запишите цифры, под которыми они указаны.\n1) Павел может быть привлечён к административной ответственности, так как достиг 16 лет.\n2) К Павлу не может быть применён административный арест.\n3) Дело может быть рассмотрено комиссией по делам несовершеннолетних и защите их прав.\n4) Административная ответственность наступает только с 18 лет.\n5) За мелкое хулиганство Павлу может быть назначено наказание в виде лишения свободы.',
      a: '123', s: ['1 — ст. 2.3 КоАП РФ: административная ответственность наступает с 16 лет (4 — неверно).', '2 — ст. 3.9 КоАП РФ: административный арест не применяется к лицам до 18 лет.', '3 — дела о правонарушениях несовершеннолетних рассматривают комиссии по делам несовершеннолетних.', '5 — неверно: лишение свободы — уголовное наказание.'] },
    { q: 'Четырнадцатилетний Денис украл мобильный телефон у одноклассника. Выберите верные утверждения и запишите цифры, под которыми они указаны.\n1) Денис может быть привлечён к уголовной ответственности, так как за кражу она наступает с 14 лет.\n2) Кража является преступлением.\n3) Уголовная ответственность за любые преступления наступает только с 18 лет.\n4) Наказание Денису может назначить только суд.\n5) Денису может быть назначено пожизненное лишение свободы.',
      a: '124', s: ['1 — ст. 20 УК РФ: за кражу ответственность наступает с 14 лет (3 — неверно: общий возраст — 16 лет).', '2 — кража (ст. 158 УК РФ) — преступление.', '4 — наказание назначается только по приговору суда.', '5 — неверно: пожизненное лишение свободы не назначается несовершеннолетним.'] },
    { q: 'Гражданин С. умер, не оставив завещания. У него остались жена, двое взрослых детей и мать. Выберите верные утверждения и запишите цифры, под которыми они указаны.\n1) Все перечисленные родственники являются наследниками первой очереди.\n2) Наследники одной очереди наследуют в равных долях.\n3) Имущество С. перейдёт к государству, так как завещания нет.\n4) Наследство может быть принято в течение шести месяцев со дня открытия наследства.\n5) Мать С. может получить наследство только по завещанию.',
      a: '124', s: ['1, 2 — ст. 1141, 1142 ГК РФ: дети, супруг и родители — наследники первой очереди, наследуют в равных долях.', '4 — ст. 1154 ГК РФ: верно.', '3, 5 — неверно: при отсутствии завещания действует наследование по закону, мать — наследник первой очереди.'] },
    { q: 'Супруги К. решили расторгнуть брак. У них есть общий ребёнок 6 лет; оба супруга согласны на развод. Выберите верные утверждения и запишите цифры, под которыми они указаны.\n1) Брак будет расторгнут в суде, так как у супругов есть общий несовершеннолетний ребёнок.\n2) Брак может быть расторгнут в органах ЗАГС, так как оба супруга согласны.\n3) Супруги вправе заключить соглашение о том, с кем будет проживать ребёнок, и об уплате алиментов.\n4) Имущество, нажитое супругами во время брака, по общему правилу является их совместной собственностью.\n5) Родитель, который после развода будет жить отдельно, утрачивает права в отношении ребёнка.',
      a: '134', s: ['1 — ст. 21 СК РФ: при наличии общих несовершеннолетних детей брак расторгается в суде (2 — неверно).', '3 — ст. 24 СК РФ; 4 — ст. 34 СК РФ: верно.', '5 — неверно: родитель, проживающий отдельно, сохраняет права и обязанности (ст. 66 СК РФ).'] },
    { q: 'Гражданину РФ Олегу исполнилось 18 лет. Выберите верные утверждения и запишите цифры, под которыми они указаны.\n1) Олег вправе голосовать на выборах Президента РФ.\n2) Олег может быть избран депутатом Государственной Думы.\n3) Олег вправе участвовать в референдуме.\n4) С 18 лет гражданин по общему правилу приобретает дееспособность в полном объёме.\n5) Олег может быть избран Президентом РФ.',
      a: '134', s: ['1, 3 — активное избирательное право и право на участие в референдуме возникают с 18 лет.', '4 — ст. 21 ГК РФ: верно.', '2 — неверно: депутатом Госдумы можно стать с 21 года.', '5 — неверно: Президентом может быть избран гражданин не моложе 35 лет.'] }
  ],
  16: [
    { q: 'Установите соответствие между примерами правоотношений и отраслями права: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИМЕРЫ\nА) работнику объявлен выговор за прогул\nБ) суд назначил подсудимому наказание за кражу\nВ) гражданин унаследовал дом по завещанию\nГ) водитель оштрафован за нарушение правил парковки\nД) сосед возместил вред, причинённый заливом квартиры\n\nОТРАСЛИ ПРАВА\n1) гражданское\n2) трудовое\n3) административное\n4) уголовное',
      a: '24131', cols: ['Примеры', 'Отрасли права'], s: ['Трудовое (2): дисциплинарное взыскание (А).', 'Уголовное (4): наказание за кражу (Б).', 'Гражданское (1): наследование, возмещение вреда (В, Д).', 'Административное (3): штраф за нарушение правил парковки (Г).'] },
    { q: 'Установите соответствие между мерами ответственности и видами юридической ответственности: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nМЕРЫ ОТВЕТСТВЕННОСТИ\nА) выговор\nБ) административный арест\nВ) лишение свободы на определённый срок\nГ) взыскание неустойки по договору\nД) увольнение по соответствующим основаниям\n\nВИДЫ ОТВЕТСТВЕННОСТИ\n1) дисциплинарная\n2) административная\n3) уголовная\n4) гражданско-правовая',
      a: '12341', cols: ['Меры ответственности', 'Виды ответственности'], s: ['Дисциплинарная (1): замечание, выговор, увольнение (А, Д).', 'Административная (2): административный арест (Б).', 'Уголовная (3): лишение свободы (В).', 'Гражданско-правовая (4): неустойка, возмещение убытков (Г).'] },
    { q: 'Установите соответствие между правовыми нормами и отраслями права, которые их содержат: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nНОРМЫ\nА) право работника на ежегодный оплачиваемый отпуск\nБ) порядок выборов Президента РФ\nВ) порядок заключения договора дарения\nГ) обязанность родителей содержать своих несовершеннолетних детей\nД) основания приобретения гражданства РФ\n\nОТРАСЛИ ПРАВА\n1) конституционное\n2) семейное\n3) трудовое\n4) гражданское',
      a: '31421', cols: ['Нормы', 'Отрасли права'], s: ['Трудовое (3): отпуск (А).', 'Конституционное (1): выборы Президента, гражданство (Б, Д).', 'Гражданское (4): договор дарения (В).', 'Семейное (2): обязанности родителей (Г).'] },
    { q: 'Установите соответствие между отраслями права и сферами права, к которым они относятся: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nОТРАСЛИ ПРАВА\nА) гражданское\nБ) уголовное\nВ) финансовое\nГ) семейное\nД) конституционное\n\nСФЕРЫ ПРАВА\n1) публичное право\n2) частное право',
      a: '21121', cols: ['Отрасли права', 'Сферы права'], s: ['Публичное право (1) регулирует отношения с участием государства как носителя власти: уголовное, финансовое, конституционное (Б, В, Д).', 'Частное право (2) регулирует отношения равноправных лиц: гражданское, семейное (А, Г).'] },
    { q: 'Установите соответствие между отраслями права и их видами: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nОТРАСЛИ ПРАВА\nА) гражданское процессуальное\nБ) трудовое\nВ) уголовно-процессуальное\nГ) семейное\nД) земельное\n\nВИДЫ ОТРАСЛЕЙ\n1) материальные\n2) процессуальные',
      a: '21211', cols: ['Отрасли права', 'Виды отраслей'], s: ['Процессуальные отрасли (2) определяют порядок рассмотрения дел: гражданский и уголовный процесс (А, В).', 'Материальные отрасли (1) регулируют сами общественные отношения: трудовое, семейное, земельное (Б, Г, Д).'] },
    { q: 'Установите соответствие между участниками судебного процесса и видами судопроизводства: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nУЧАСТНИКИ\nА) истец\nБ) подсудимый\nВ) государственный обвинитель\nГ) ответчик\nД) потерпевший\n\nВИДЫ СУДОПРОИЗВОДСТВА\n1) гражданское\n2) уголовное',
      a: '12212', cols: ['Участники', 'Виды судопроизводства'], s: ['Гражданский процесс (1): истец и ответчик (А, Г).', 'Уголовный процесс (2): подсудимый, государственный обвинитель, потерпевший (Б, В, Д).'] },
    { q: 'Установите соответствие между правонарушениями и их видами: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРАВОНАРУШЕНИЯ\nА) убийство\nБ) безбилетный проезд в общественном транспорте\nВ) опоздание на работу\nГ) переход пешеходом проезжей части в неустановленном месте\nД) разбой\n\nВИДЫ ПРАВОНАРУШЕНИЙ\n1) преступление\n2) административный проступок\n3) дисциплинарный проступок',
      a: '12321', cols: ['Правонарушения', 'Виды правонарушений'], s: ['Преступления (1): убийство, разбой (А, Д).', 'Административные проступки (2): безбилетный проезд, нарушение правил дорожного движения пешеходом (Б, Г).', 'Дисциплинарный проступок (3): опоздание на работу (В).'] },
    { q: 'Установите соответствие между примерами правоотношений и отраслями права: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИМЕРЫ\nА) уплата гражданином транспортного налога\nБ) установление отцовства в отношении ребёнка\nВ) регистрация автомобиля в Госавтоинспекции\nГ) выдвижение кандидата в депутаты Государственной Думы\nД) усыновление ребёнка\n\nОТРАСЛИ ПРАВА\n1) финансовое\n2) семейное\n3) административное\n4) конституционное',
      a: '12342', cols: ['Примеры', 'Отрасли права'], s: ['Финансовое (1): налоги (А).', 'Семейное (2): отцовство, усыновление (Б, Д).', 'Административное (3): государственная регистрация транспортного средства (В).', 'Конституционное (4): избирательные правоотношения (Г).'] },
    { q: 'Установите соответствие между примерами правоотношений и отраслями права: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИМЕРЫ\nА) лишение родительских прав\nБ) штраф за курение в неположенном месте\nВ) аренда квартиры\nГ) осуждение за мошенничество\nД) перевод работника на другую должность\n\nОТРАСЛИ ПРАВА\n1) гражданское\n2) трудовое\n3) семейное\n4) уголовное\n5) административное',
      a: '35142', cols: ['Примеры', 'Отрасли права'], s: ['Семейное (3): лишение родительских прав (А).', 'Административное (5): штраф за курение (Б).', 'Гражданское (1): аренда (В).', 'Уголовное (4): мошенничество (Г).', 'Трудовое (2): перевод на другую работу (Д).'] }
  ]
};
Object.keys(ADD).forEach(n => S.data.find(t => t.n === +n).tasks.push(...ADD[n]));
})();
